    margin-top:0;
}

.status {
    font-size:30px;
    font-weight:bold;
    padding:25px;
    text-align:center;
    border-radius:12px;
    background:#101318;
}

.motion {
    color:#ff4040;
}

.nomotion {
    color:#45d483;
}

.raw {
    margin-top:20px;
    font-family:monospace;
    font-size:18px;
}

.log {
    border-bottom:1px solid #292e35;
    padding:12px 0;
}

.time {
    color:#5fa9ff;
}

.event {
    color:#ff6666;
}

.empty {
    color:#777;
}
</style>
</head>

<body>

<div class="container">

<h1>ESP8266 Motion Sensor</h1>

<div class="card">

<div id="status" class="status nomotion">
NO MOTION
</div>

<div class="raw">
PIR RAW: <span id="raw">LOW</span>
</div>

</div>

<div class="card">

<h2>Motion Log</h2>

<div id="log">
<div class="empty">No motion detected.</div>
</div>

</div>

</div>

<script>

let previousMotion = false;

function beep() {

    try {

        const AudioContext =
            window.AudioContext ||
            window.webkitAudioContext;

        const audio =
            new AudioContext();

        const oscillator =
            audio.createOscillator();

        const gain =
            audio.createGain();

        oscillator.frequency.value = 1000;

        oscillator.type = "square";

        gain.gain.value = 0.2;

        oscillator.connect(gain);

        gain.connect(audio.destination);

        oscillator.start();

        setTimeout(() => {
            oscillator.stop();
            audio.close();
        }, 250);

    } catch(e) {

        console.log("Audio error:", e);

    }
}


function addLog() {

    const now = new Date();

    const time =
        now.toLocaleTimeString("en-US", {
            hour12:false
        });

    const log =
        document.getElementById("log");

    const row =
        document.createElement("div");

    row.className = "log";

    row.innerHTML =
        '<span class="time">' +
        time +
        '</span> — ' +
        '<span class="event">Motion detected</span>';

    if (
        log.innerHTML.includes(
            "No motion detected"
        )
    ) {
        log.innerHTML = "";
    }

    log.prepend(row);

}


async function update() {

    try {

        const response =
            await fetch("/status");

        const data =
            await response.json();

        const status =
            document.getElementById("status");

        const raw =
            document.getElementById("raw");

        raw.innerText =
            data.raw ? "HIGH" : "LOW";


        if (data.raw) {

            status.innerText =
                "MOTION DETECTED";

            status.className =
                "status motion";

            if (!previousMotion) {

                addLog();

                beep();

            }

            previousMotion = true;

        } else {

            status.innerText =
                "NO MOTION";

            status.className =
                "status nomotion";

            previousMotion = false;

        }

    } catch(e) {

        console.log(e);

    }

}


setInterval(update, 200);

update();

</script>

</body>
</html>
)rawliteral";


void handleRoot() {

    server.send_P(
        200,
        "text/html",
        PAGE
    );

}


void handleStatus() {

    bool pir =
        digitalRead(PIR_PIN) == HIGH;

    String json =
        "{\"raw\":" +
        String(pir ? "true" : "false") +
        "}";

    server.send(
        200,
        "application/json",
        json
    );

}


void setup() {

    Serial.begin(115200);

    pinMode(
        PIR_PIN,
        INPUT
    );

    bootTime = millis();

    WiFi.mode(WIFI_AP);

    WiFi.softAP(
        WIFI_NAME,
        WIFI_PASS
    );

    Serial.println();
    Serial.println("==========================");
    Serial.println("ESP8266 MOTION SENSOR");
    Serial.println("==========================");

    Serial.print("SSID: ");
    Serial.println(WIFI_NAME);

    Serial.print("IP: ");
    Serial.println(
        WiFi.softAPIP()
    );

    server.on(
        "/",
        handleRoot
    );

    server.on(
        "/status",
        handleStatus
    );

    server.begin();

    Serial.println("Server started.");
}


void loop() {

    server.handleClient();

}
